"""Static, dependency-free Studio projection; no server or mutation authority."""
import json
from pathlib import Path
from .parser import ProductError
from .repository import Repository
from .graph import ProductGraph
from .engine import check,accepted
from .context import compile_context
from .compiler import render_context

HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenProduct Studio</title>
<style>
:root{--paper:#f4f1e8;--ink:#222d28;--line:#cfcfc1;--green:#315b47;--muted:#69776d;--red:#923f32}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 'Trebuchet MS',sans-serif}header{padding:36px 5vw 28px;border-bottom:1px solid var(--ink);display:flex;justify-content:space-between;gap:30px;align-items:end}h1{font:normal 44px/1 Georgia,serif;letter-spacing:-2px;margin:0 0 15px}h2{font:normal 30px Georgia,serif;margin:0 0 12px}h3{font-size:12px;text-transform:uppercase;letter-spacing:1.5px;margin-top:28px}.kicker{font-size:11px;text-transform:uppercase;letter-spacing:3px;color:var(--muted);margin-bottom:17px}.summary{max-width:550px;font-size:13px}.tag{display:inline-block;border:1px solid var(--green);padding:3px 9px;margin:3px 6px 3px 0;border-radius:2px;font:11px 'Trebuchet MS',sans-serif;color:var(--green)}.fail{color:var(--red);border-color:var(--red)}main{display:grid;grid-template-columns:310px minmax(0,1fr);min-height:75vh;margin:0 5vw}aside{border-right:1px solid var(--line);padding:25px 25px 25px 0}input,select{width:100%;padding:12px 10px;border:1px solid var(--line);background:#faf9f3;color:var(--ink);font:inherit;margin-bottom:10px}a.download{display:inline-block;text-decoration:none;border:1px solid var(--line);padding:9px 12px;color:var(--ink)}textarea{width:100%;min-height:240px;background:#faf9f3;border:1px solid var(--line);padding:14px;font:12px/1.6 Consolas,monospace}button{font:inherit;cursor:pointer;background:transparent;color:var(--ink);border:1px solid var(--line);padding:9px 12px}button:hover,button:focus-visible{background:#e1e7dc;outline:2px solid var(--green);outline-offset:2px}.object{display:block;text-align:left;width:100%;border:0;border-bottom:1px solid var(--line);padding:16px 10px}.object.active{border-left:3px solid var(--green);background:#e1e7dc}.object small{display:block;color:var(--muted);font-size:11px;margin-top:5px}.detail{padding:35px 0 45px 38px;max-width:1100px}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:25px 0}.primary{background:var(--green);color:#fff;border-color:var(--green)}.primary:hover{color:var(--ink)}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eae9df;border-left:3px solid var(--line);padding:18px;font:12px/1.65 Consolas,monospace}.body{white-space:pre-wrap;border-bottom:1px solid var(--line);padding-bottom:20px;overflow-wrap:anywhere}.edge{margin:5px 8px 5px 0;font-size:12px}.empty{color:var(--muted);font-size:13px}footer{padding:22px 5vw;border-top:1px solid var(--ink);font-size:12px;color:var(--muted)}#notice{font-size:12px;color:var(--green)}details{margin-top:22px}summary{cursor:pointer;font-size:13px}.alert{color:var(--red)}@media(max-width:760px){header{display:block;padding:25px 6vw}h1{font-size:36px}.summary{margin-top:20px}main{display:block;margin:0 6vw}aside{border-right:0;padding-right:0;max-height:330px;overflow:auto;border-bottom:1px solid var(--ink)}.detail{padding:28px 0}footer{padding:20px 6vw}}@media(prefers-reduced-motion:no-preference){.detail{animation:reveal .3s ease-out}@keyframes reveal{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}}
</style></head><body><header><div><div class="kicker">A file-native product workspace</div><h1>OpenProduct Studio</h1><div id="project"></div></div><div class="summary"><div id="checks"></div><div id="authority"></div></div></header><main><aside><label for="search" class="kicker">Find an object</label><input id="search" placeholder="ID or title" autocomplete="off"><label for="type" class="kicker">Product type</label><select id="type"><option value="">All types</option></select><div id="list"></div></aside><article class="detail" id="detail"><p class="empty">Choose an object to inspect its Product meaning and relations.</p></article></main><footer>Working-tree projection · Direct Markdown edits own Product meaning · Git and current CheckProof establish accepted state · Studio never grants integration authority.</footer><script id="product-data" type="application/json">__DATA__</script><script>
'use strict';
const data=JSON.parse(document.getElementById('product-data').textContent);let selected=null;
const byId=new Map(data.objects.map(o=>[o.frontmatter.id,o]));
const el=(name,text,cls)=>{const n=document.createElement(name);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
document.getElementById('project').textContent=data.project;
const checks=document.getElementById('checks');checks.append(el('span','Working check: '+data.working.result,'tag'+(data.working.result==='PASS'?'':' fail')),el('span','Accepted canonical: '+data.accepted.result,'tag'+(data.accepted.result==='PASS'?'':' fail')));
document.getElementById('authority').textContent=data.accepted.result==='PASS'?'Canonical commit '+data.accepted.commit:'Canonical state needs current valid proof.';
for(const kind of [...new Set(data.objects.map(o=>o.frontmatter.type))].sort()){const option=el('option',kind);option.value=kind;document.getElementById('type').append(option)}
function list(){const box=document.getElementById('list');box.replaceChildren();const query=document.getElementById('search').value.toLowerCase(),kind=document.getElementById('type').value;const matches=data.objects.filter(o=>(!kind||o.frontmatter.type===kind)&&(o.frontmatter.id+' '+o.frontmatter.title).toLowerCase().includes(query));for(const o of matches){const b=el('button',o.frontmatter.title,'object'+(selected===o.frontmatter.id?' active':''));b.append(el('small',o.frontmatter.id+' / '+o.frontmatter.type));b.onclick=()=>show(o.frontmatter.id);box.append(b)}if(!matches.length)box.append(el('p','No matching objects.','empty'))}
function show(id){selected=id;list();const o=byId.get(id),f=o.frontmatter,box=document.getElementById('detail');box.replaceChildren(el('div',f.type+' / '+id,'kicker'),el('h2',f.title));box.append(el('span',f.status,'tag'),el('span','Revision '+f.revision,'tag'));const bar=el('div',undefined,'toolbar'),copy=el('button','Copy for Agent','primary'),download=el('a','Download context','download'),notice=el('span','');notice.id='notice';notice.setAttribute('role','status');copy.onclick=async()=>{const text=data.contexts[id].text;try{await navigator.clipboard.writeText(text);notice.textContent='Task context copied.'}catch(e){const area=el('textarea',text);area.value=text;document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();notice.textContent=ok?'Task context copied.':'Use Download context to save the bundle.'}};download.href='data:text/markdown;charset=utf-8,'+encodeURIComponent(data.contexts[id].text);download.download=id+'-context.md';bar.append(copy,download,notice);box.append(bar);for(const [name,text]of Object.entries(o.sections).sort()){box.append(el('h3',name),el('div',text,'body'))}box.append(el('h3','Source-owned relations'));if(!f.relations.length)box.append(el('p','No outgoing relations.','empty'));for(const r of f.relations){const b=el('button',r.kind+' → '+r.target,'edge');b.disabled=!byId.has(r.target);b.onclick=()=>show(r.target);box.append(b)}box.append(el('h3','Derived incoming relations'));const incoming=data.incoming[id]||[];if(!incoming.length)box.append(el('p','No incoming relations.','empty'));for(const [source,r]of incoming){const b=el('button',source+' → '+r.kind,'edge');b.onclick=()=>show(source);box.append(b)}const findings=data.working.errors.filter(e=>e.objects.includes(id));if(findings.length){box.append(el('h3','Check findings'));for(const e of findings)box.append(el('p',e.code+': '+e.explanation,'alert'))}const details=el('details'),summary=el('summary','Canonical fields and scoped context identity');const preview=el('textarea');preview.readOnly=true;preview.value=data.contexts[id].text;preview.setAttribute('aria-label','Task context for agent');details.append(summary,el('pre',JSON.stringify(f,null,2)),el('pre','contextFingerprint: '+data.contexts[id].fingerprint+'\ncontextObjectSet: '+data.contexts[id].ids.join(', ')),preview);box.append(details)}
document.getElementById('search').oninput=list;document.getElementById('type').onchange=list;list();if(data.objects.length)show(data.objects[0].frontmatter.id);
</script></body></html>'''

def build(root,output,whole=False):
    if not whole:
        raise ProductError('SCHEMA_INVALID','Studio is an explicit whole-graph projection; pass --whole')
    repo=Repository(root)
    config,objects=repo.snapshot()
    graph=ProductGraph(objects)
    contexts={}
    for id in sorted(objects):
        context=compile_context(root,[id])
        contexts[id]=dict(text=render_context(context),fingerprint=context['contextFingerprint'],ids=context['contextObjectSet'])
    payload=dict(project=config['project'].get('name',config['project']['canonicalRef']),objects=[objects[id] for id in sorted(objects)],incoming=graph.incoming,working=check(root),accepted=accepted(root),contexts=contexts)
    encoded=json.dumps(payload,ensure_ascii=False).replace('<',r'\u003c').replace('>',r'\u003e').replace('&',r'\u0026')
    output=Path(output).resolve()
    # A generated projection must never overwrite normative Product files.
    product=repo.root / '.openproduct'
    if output.suffix.lower() != '.html':
        raise ProductError('SCHEMA_INVALID','Studio output must be an HTML file')
    if output == product or product in output.parents:
        raise ProductError('SCHEMA_INVALID','Write Studio outside .openproduct')
    output.parent.mkdir(parents=True,exist_ok=True)
    output.write_text(HTML.replace('__DATA__',encoded),encoding='utf-8')
    return dict(result='PASS',path=str(output),objects=len(objects))
